using System;using System.IO;using System.Drawing;using System.Windows.Forms;
namespace FleetLab
{
    internal static class PracticeFormationPresetFormChecks
    {
        static T C<T>(Form f,string n)where T:Control{return(T)f.Controls.Find(n,true)[0];}static void Need(bool v,string m){if(!v)throw new Exception(m);}static void Click(Form f,string n){C<Button>(f,n).PerformClick();Application.DoEvents();}static void Show(Form f,Form owner){f.Show(owner);Application.DoEvents();}
        internal static void Run(Action<string,Action> check,string assets,Form owner)
        {
            check("Formation inspector exposes forty raw records and complete readonly10x10 values",delegate{using(var parent=new PracticeGeneratedReinforcementStudy(Path.Combine(Path.GetDirectoryName(assets),"Programs")))using(var f=new PracticeFormationPresetStudy(assets)){Need(parent.Controls.Find("generatedFormationPresets",true).Length==1,"Discoverable formation entry");Show(f,owner);Need(C<ListBox>(f,"presetList").Items.Count==40&&f.SelectedPreset.Slot==0&&f.SelectedPreset.RawOwner==255,"Pinned raw firstrecord");var g=C<DataGridView>(f,"presetGrid");Need(g.RowHeadersWidth>=50&&g.ReadOnly&&g.Rows.Count==10&&g.Columns.Count==10&&(int)g.Rows[0].Cells[0].Value==1,"Complete raw grid");Need(C<Label>(f,"presetSummary").Text.Contains("4056")&&C<TextBox>(f,"presetDetails").ReadOnly,"Retained trailer and readonly details");}});
            check("Formation CPU filter shows sixteen tag10 candidates and selects final record39",delegate{using(var f=new PracticeFormationPresetStudy(assets)){Show(f,owner);Click(f,"presetCpu");var list=C<ListBox>(f,"presetList");Need(list.Items.Count==16&&f.SelectedPreset.Kind==10&&f.SelectedPreset.Slot==24,"CPU tagfilter sourcebasis");list.SelectedIndex=15;Application.DoEvents();Need(f.SelectedPreset.Slot==39&&(int)C<DataGridView>(f,"presetGrid").Rows[9].Cells[9].Value==f.SelectedPreset.CellAt(99)&&C<TextBox>(f,"presetDetails").Text.Contains("Slot 39"),"Last cell/record data follows selection");}});
            check("Formation tag9 filter and reset retain source count and early terminator metadata",delegate{using(var f=new PracticeFormationPresetStudy(assets)){Show(f,owner);C<ComboBox>(f,"presetFilter").SelectedIndex=1;Need(C<ListBox>(f,"presetList").Items.Count==24&&f.SelectedPreset.Kind==9,"Tag9filter");Click(f,"presetCpu");C<ListBox>(f,"presetList").SelectedIndex=15;Click(f,"presetReset");Need(C<ComboBox>(f,"presetFilter").SelectedIndex==0&&C<ListBox>(f,"presetList").Items.Count==40&&f.SelectedPreset.Slot==0&&f.Snapshot.ConsumedBytes==16081&&f.Snapshot.CopyTrailingBytes().Length==4056,"Reset inspection does not modify loaded data");Need(C<ComboBox>(f,"presetFilter").ForeColor!=C<ComboBox>(f,"presetFilter").BackColor,"Readable selectedfilter");}});
            check("Formation minimum scrolling preserves fixed Close and selected data closes cleanly",delegate{using(var f=new PracticeFormationPresetStudy(assets)){Show(f,owner);Click(f,"presetCpu");C<ListBox>(f,"presetList").SelectedIndex=15;f.ClientSize=new Size(940,620);var d=C<TextBox>(f,"presetDetails");d.Focus();C<Panel>(f,"presetScroll").ScrollControlIntoView(d);Application.DoEvents();var close=C<Button>(f,"presetClose");Need(d.Width>=860&&f.ClientRectangle.Contains(new Rectangle(f.PointToClient(close.PointToScreen(Point.Empty)),close.Size)),"Scrollable details/fixedClose");Click(f,"presetClose");Need(f.IsDisposed||!f.Visible,"Clean selectedrecord disposal");}});
        }
        static void Save(Form f,string o,string n){Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(o,n+".png"),System.Drawing.Imaging.ImageFormat.Png);}}
        internal static int SavePreviews(string assets,string output)
        {
            try{Directory.CreateDirectory(output);using(var f=new PracticeFormationPresetStudy(assets)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();Save(f,output,"01-all-records");Click(f,"presetCpu");Save(f,output,"02-cpu-candidates");C<ListBox>(f,"presetList").SelectedIndex=15;Save(f,output,"03-last-candidate");C<ComboBox>(f,"presetFilter").SelectedIndex=1;Save(f,output,"04-tag9");f.ClientSize=new Size(940,620);var d=C<TextBox>(f,"presetDetails");d.Focus();C<Panel>(f,"presetScroll").ScrollControlIntoView(d);Save(f,output,"05-minimum-details");var g=C<DataGridView>(f,"presetGrid");g.Focus();C<Panel>(f,"presetScroll").ScrollControlIntoView(g);Save(f,output,"06-minimum-grid");f.Close();}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"Error.txt"),ex.ToString());return 1;}
        }
    }
}
